insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r29-v2','0.2.0','Lesson 6 step 2 of 6: Does this paragraph contain it?','reading','guided_practice','Read LEARN FIRST and the worked examples. Then read only the paragraph named in each question and choose YES or NO.','Say YES only if the paragraph has the right KIND of information, about the right TOPIC, and you can copy the PROOF.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph C: does it contain a caution against drawing wide conclusions from evidence collected at one location?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q2", "prompt": "Paragraph A: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q3", "prompt": "Paragraph F: does it contain the justification some local authorities give for offering financial help?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q4", "prompt": "Paragraph F: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q5", "prompt": "Paragraph B: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q6", "prompt": "Paragraph D: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 YES. Kind: a caution. Proof: \"readings taken on a single rooftop reveal little about conditions in the surrounding district\". One location = a single rooftop.\n2 NO. A mentions the hours after dusk, but only describes temperatures. Nothing about people or coping: the topic matches, the kind does not.\n3 NO. F mentions grants, but it warns about where they go. It gives no reason for offering them. Echo word, wrong meaning.\n4 YES. Kind: an option (cool roofs). Proof: \"far cheaper on buildings whose structure cannot support soil\".\n5 YES. Proof: \"bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Overnight = after dark; less able to withstand = weaker capacity to cope.\n6 NO. D says older buildings \"could not bear the additional load\", which names the problem but offers no option. Half an answer is a wrong answer.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail: decide whether one paragraph contains a given kind of information."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: check one paragraph in three questions

Read only the paragraph named. Ask three questions:
1. KIND: is the right kind of information there (an account, a caution, an option...)?
2. TOPIC: is it about the right thing?
3. PROOF: can I copy the words that show it?
Only if all three are YES is the answer YES.

WORKED EXAMPLE 1
"Paragraph E: does it contain a complaint about who pays for green roofs?"
Kind: a complaint. Topic: who pays. Proof: "the financial burden falls entirely on them".  -> YES

WORKED EXAMPLE 2
"Paragraph C: does it contain a complaint about who pays for green roofs?"
C explains how green roofs cool buildings. There is no complaint and nothing about money.  -> NO
The topic (green roofs) is the same, but the KIND of information is missing.' || '

- - - - - - - - - - - - - - - - - - - -

' || 'THE PASSAGE: Cooling the city from the roof up

A. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.

B. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.

C. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.

D. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.

E. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.

F. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.')),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb,'6bb73ed1caf02b82aaa4895675e397b547f9647b7177cee6a1e362901c9f4cb8',true) on conflict (code) do nothing;
